Scoring Engine Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Scoring Engine Container container

Container_Boundary(scoring_engine_container, "Scoring Engine Container") {
    Component(Scoring Engine Container, "Scoring Engine Container", "AWS ECS on Fargate, Protocol Buffers", "Screens card-not-present payment authorizations for fraud prior to approval.")
}

System_Ext(Amazon S3, "Amazon S3", "AWS S3 with Object Lock")
System_Ext(AWS Systems Manager Parameter Store, "AWS Systems Manager Parameter Store", "AWS Systems Manager")

Rel(Scoring Engine Container, Amazon S3, "Loads model bundles and writes tamper-evident audit records", "HTTPS / TLS")
Rel(Scoring Engine Container, AWS Systems Manager Parameter Store, "Reads configuration", "AWS API")

@enduml

Amazon S3.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container(scoring_engine, "Scoring Engine Container", "AWS ECS on Fargate, Protocol Buffers", "Evaluates card-not-present payment authorizations.")

Container_Boundary(amazon_s3, "Amazon S3") {
    Component(Model_Bundle_Storage, "Model Bundle Storage", "AWS S3 Bucket with VPC Gateway Endpoints", "Stores machine learning model bundles loaded by the Scoring Engine Container.")
    Component(Audit_Record_Store, "Audit Record Store", "AWS S3 with Object Lock and SSE-KMS", "Provides tamper-evident WORM storage for immutable 7-year audit records.")
}

Rel(scoring_engine, Model_Bundle_Storage, "Loads model bundles", "HTTPS / TLS")
Rel(scoring_engine, Audit_Record_Store, "Writes tamper-evident audit records", "HTTPS / TLS")

@enduml

Amazon Aurora Serverless.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_aurora_serverless, "Amazon Aurora Serverless") {
    Component(Relational Database Engine, "Relational Database Engine", "Amazon Aurora Serverless v2", "Provides relational storage for case management with strictly bounded ACUs to respect budget constraints.")
    Component(Change Data Capture (CDC) Publisher, "Change Data Capture (CDC) Publisher", "AWS Database Migration Service", "Streams change data capture audit logs asynchronously from the database.")
}

Rel(Relational Database Engine, Change Data Capture (CDC) Publisher, "Streams change data capture audit logs asynchronously", "TLS/HTTPS")

@enduml

AWS Systems Manager Parameter Store.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS Systems Manager Parameter Store container

Container_Boundary(aws_systems_manager_parameter_store, "AWS Systems Manager Parameter Store") {
    Component(Configuration_and_Secrets_Manager, "Configuration and Secrets Manager", "AWS Systems Manager / AWS KMS", "Centralizes runtime configuration and secrets management using SecureString parameters.")
}

System_Ext(Scoring_Engine_Container, "Scoring Engine Container", "AWS ECS on Fargate")
System_Ext(Case_Management_and_Admin_Container, "Case Management & Admin Container", "AWS ECS on Fargate")

Rel(Configuration_and_Secrets_Manager, Scoring_Engine_Container, "Provides runtime configuration and secrets", "AWS API")
Rel(Configuration_and_Secrets_Manager, Case_Management_and_Admin_Container, "Provides and receives configuration and secrets updates", "AWS API")

@enduml
